/* @lc app=leetcode id=1537 lang=kotlin */ class Solution { fun seg(a: IntArray, cs: Set<Int>): List<Long> = a.fold(mutableListOf(0L)) { l, x -> if (x in cs) l.also { it.add(0L) } else l.also { it[it.size - 1] += x } } fun maxSum(nums1: IntArray, nums2: IntArray): Int = nums1.toSet().intersect(nums2.toSet()).let { cs -> ((seg(nums1, cs) zip seg(nums2, cs)).sumOf { maxOf(it.first, it.second) } + cs.sumOf { it.toLong() }) % 1_000_000_007 }.toInt() }